const ALIASES = {
  hadoop: 'hdfs',
  dockercompose: 'docker',
  composer: 'docker',
  k8s: 'kubernetes',
  postgres: 'postgresql',
  apachekafka: 'kafka',
  apachespark: 'spark',
  apacheparquet: 'parquet',
  sonar: 'sonarqube',
};

export function toolLogo(name) {
  const key = String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
  return TOOL_LOGOS[ALIASES[key] ?? key] ?? null;
}
